It can be seen right from the definition that whenever $x^*\in\dom\phi$ is a local minimizer
of $\phi$, then $0\in\widehat\partial\phi(x^*)$, which is referred to as Fermat's rule,
see \cite[Proposition~1.30(i)]{Mordukhovich2018}.

Given $ x \in \dom\phi $, the limiting subdifferential has the important robustness
property 
\begin{equation}\label{Eq:robustness}
   \left\{ 
   	\eta\in\mathbb X\,\middle|\,
   	\exists\{x^k\},\{\eta^k\}\subset\mathbb X\colon\,x^k\to_\phi x,\,\eta^k\to\eta,\,\eta^k\in\partial\phi(x^k)\,\forall k\in\N
   \right\}
   \subset
   \partial\phi(x),
\end{equation}

Whenever $x\in\dom\phi$ is fixed, the sum rule
\begin{equation}
		\label{eq:regular_sum_rule}
		\widehat{\partial}(f+\phi)(x)
		=
		\nabla f(x)+\widehat{\partial}\phi(x)
\end{equation}

\begin{algorithm}[Monotone Proximal Gradient Method]\leavevmode
	\label{Alg:MonotoneProxGrad}
	\begin{algorithmic}[1]
		\REQUIRE $ \tau > 1, 0 < \gamma_{\min} \leq  \gamma_{\max} < \infty, \delta \in (0,1), x^0 \in \dom\phi $
		\STATE Set $k := 0$.
		\WHILE{A suitable termination criterion is violated at iteration $ k $}
		\STATE Choose $ \gamma_k^0 \in [ \gamma_{\min}, \gamma_{\max}] $.
		\STATE\label{step:subproblem_solve_MonotoneProxGrad} 
			For $ i = 0, 1, 2, \ldots $, compute a solution $ x^{k,i} $ of
      		\begin{equation}\label{Eq:Subki}
         		\min_x \ f (x^k) + \langle\nabla f(x^k), x - x^k \rangle + \frac{\gamma_{k,i}}{2} \| x - x^k \|^2 + \phi (x), 
         		\quad x \in \mathbb X
      		\end{equation}
      		with $ \gamma_{k,i} := \tau^i \gamma_k^0 $, until the acceptance criterion
      		\begin{equation}\label{Eq:StepCrit}
         		\psi (x^{k,i}) \leq 
         		\psi (x^k) - \delta \frac{\gamma_{k,i}}{2} \| x^{k,i} - x^k \|^2 
      		\end{equation}
      		holds.
		\STATE Denote by $ i_k := i $ the terminal value, and set $ \gamma_k := 
      			\gamma_{k,i_k} $ and $ x^{k+1} := x^{k,i_k} $.
      	\STATE Set $ k \leftarrow k + 1 $.
		\ENDWHILE
		\RETURN $x^k$
	\end{algorithmic}
\end{algorithm}

\begin{assumption}\label{Ass:ProxGradMonotone}
\begin{enumerate}
   \item \label{item:psi_bounded} The function $ \psi $ is bounded from below on $ \dom\phi $.
   \item \label{item:phi_bounded_affine} The function  $ \phi $ is bounded from below by an affine function.
\end{enumerate}
\end{assumption}

