\begin{assumption}\label{Ass:ProxGradMonotone}
\begin{enumerate}
   \item \label{item:psi_bounded} The function $ \psi $ is bounded from below on $ \dom\phi $.
   \item \label{item:phi_bounded_affine} The function  $ \phi $ is bounded from below by an affine function.
\end{enumerate}
\end{assumption}

\begin{lemma}\label{Lem:StepsizeFinite}
Consider a fixed iteration $ k $ of \cref{Alg:MonotoneProxGrad}, assume that $ x^k $ is not an M-stationary point of
\eqref{Eq:P}, and suppose that \Cref{Ass:ProxGradMonotone}~\ref{item:phi_bounded_affine} holds. Then the inner 
loop in \cref{step:subproblem_solve_MonotoneProxGrad} of \Cref{Alg:MonotoneProxGrad} is finite, i.e., we have $ \gamma_k = \gamma_{k,i_k} $
for some finite index $ i_k \in \{ 0, 1, 2, \ldots \} $.
\end{lemma}

\begin{proof}
	Suppose that the inner loop of \cref{Alg:MonotoneProxGrad} does not
	terminate after a finite number of steps in iteration $k$.
Recall that $ x^{k,i} $ is a solution of \eqref{Eq:Subki}. Therefore, we get
\begin{equation}\label{Eq:Sub1i}
   \langle \nabla f(x^k),x^{k,i} - x^k\rangle +    \frac{\gamma_{k,i}}{2} \| x^{k,i} - x^k \|^2 + \phi (x^{k,i}) \leq \phi (x^k).
\end{equation}

We claim that
\begin{equation}\label{Eq:Sub2i}
   \liminf_{i \to \infty} \gamma_{k,i} \| x^{k,i} - x^k \| > 0.
\end{equation}
Assume, by contradiction, that there is a subsequence $ i_l \to \infty $ such that 
\begin{equation}\label{Eq:Sub3i}
   \liminf_{l \to \infty} \gamma_{k, i_l} \| x^{k, i_l} - x^k \| = 0. 
\end{equation}
Since $ x^{k,i_l} $ is optimal for \eqref{Eq:Subki}, Fermat's rule and the sum rule
\eqref{eq:regular_sum_rule} yield
\begin{equation}\label{eq:optimality_condition_subproblem}
   0 \in  \nabla f (x^k) + \gamma_{k, i_l} ( x^{k, i_l} - x^k ) +
   \widehat\partial \phi (x^{k,i_l})
\end{equation}
for all $l\in\N$.
Taking the limit $ l \to \infty $ while using \eqref{eq:robustsum} and \eqref{Eq:Sub3i},
we obtain
\begin{equation*}
   0 \in  \nabla f (x^k) + \partial \phi (x^k),
\end{equation*}
which means that $ x^k $ is already an M-stationary point of \eqref{Eq:P}. This 
contradiction shows that \eqref{Eq:Sub2i} holds. Hence, there is a constant $ c > 0 $
such that
\begin{equation*}
   \gamma_{k,i} \| x^{k,i} - x^k \| \geq c 
\end{equation*}
holds for all large enough $i\in\N$.

In particular, this implies
\begin{equation}\label{Eq:Sub4i}
   ( 1- \delta ) \frac{\gamma_{k,i}}{2} \| x^{k,i} - x^k \|^2 \geq 
   \frac{1- \delta}{2} c \| x^{k,i} - x^k \| \geq o \big( \| x^{k,i} - x^k \| \big)
\end{equation}
for all sufficiently large $i\in\N$.
Furthermore, \eqref{Eq:Sub1i} shows that
\begin{equation}\label{Eq:Sub5i}
	\langle \nabla f (x^k),x^{k,i} - x^k\rangle +
   \phi \big( x^{k,i} \big) - \phi (x^k)
   \leq
   - \frac{\gamma_{k,i}}{2} \| x^{k,i} - x^k \|^2 .
\end{equation}

\begin{proposition}\label{Prop:xdiff}
Let \Cref{Ass:ProxGradMonotone} hold. Then each sequence 
$ \{ x^k \} $ generated by \Cref{Alg:MonotoneProxGrad} satisfies
$ \| x^{k+1} - x^k \| \to 0 $.
\end{proposition}

\begin{proof}
First recall that the sequence $ \{ x^k \} $ is well-defined by \Cref{Lem:StepsizeFinite}.
Using the acceptance criterion \eqref{Eq:StepCrit}, we get
\begin{equation}\label{Eq:xdiff-1}
   \psi (x^{k+1}) \leq \psi (x^k) - \delta \frac{\gamma_k}{2} \| x^{k+1} - x^k \|^2 
   \leq \psi (x^k)
\end{equation}
for all $ k \in \mathbb{{N}} $. Hence, the sequence $ \{ \psi (x^k) \} $ is 
monotonically decreasing. Since $ \psi $ is bounded from below on $ \dom\phi $
by \Cref{Ass:ProxGradMonotone}~\ref{item:psi_bounded} and $ \{ x^k \} \subset \dom\phi $, it follows that
this sequence is convergent. Therefore, \eqref{Eq:xdiff-1} implies
\begin{equation*}
   \gamma_k \| x^{k+1} - x^k \|^2 \to 0 \quad \text{for } k \to \infty .
\end{equation*}
Hence the assertion follows from the fact that, by 
construction, we have $ \gamma_k \geq \gamma_{\min} > 0 $ for all $ k \in \mathbb{N} $.
\end{proof}

