\begin{proposition}\label{Prop:gammaxdiff}
Let \Cref{Ass:ProxGradMonotone} hold, let $\{x^k\}$ be a sequence generated by \cref{Alg:MonotoneProxGrad}, 
and let $ \{ x^k \}_K $ be a subsequence converging
to some point $ x^* $. Then $ \gamma_k \| x^{k+1} - x^k \| \to_K 0 $ holds.
\end{proposition}

Now, by the mean-value theorem, there exists $ \xi^k $ on the line segment connecting
$ x^k $ with $ \hat{x}^k $ such that
\begin{equation}\label{Prop:gammaxdiff-3}
	\begin{aligned}
   		\psi ( \hat{x}^k ) - \psi (x^k) 
   		&= 
   		f ( \hat{x}^k ) + \phi (\hat{x}^k) -   f (x^k) - \phi (x^k) \\
   		&= 
   		\langle  \nabla f (\xi^k),\hat{x}^k - x^k \rangle + \phi (\hat{x}^k) - \phi (x^k) .
   \end{aligned}
\end{equation}
Substituting the expression $ \phi (\hat{x}^k) - \phi (x^k) $ from \eqref{Prop:gammaxdiff-3}
into \eqref{Prop:gammaxdiff-2} yields 
\begin{equation*}
   \langle \nabla f(x^k) - \nabla f ( \xi^k) ,\hat x^k - x^k \rangle +
   \frac{\hat{\gamma}_k}{2} \| \hat{x}^k - x^k \|^2 + \psi ( \hat{x}^k ) - \psi (x^k) \leq 0.
\end{equation*}

\begin{corollary}\label{Cor:LipschitzCase}
Let \Cref{Ass:ProxGradMonotone} hold, let $\{x^k\}$ be a sequence generated by \Cref{Alg:MonotoneProxGrad}, let $ \{ x^k \}_K $ be a subsequence converging
to some point $ x^* $, and assume that $ \nabla f \colon \mathbb X\to\mathbb X$ is locally Lipschitz continuous
around $ x^* $. Then the corresponding subsequence $ \{ \gamma_k \}_K $ is
bounded.
\end{corollary}

\begin{theorem}\label{Thm:ConvProxGrad}
Assume that \Cref{Ass:ProxGradMonotone} holds while either $ \phi $ is continuous
on $\dom\phi$ or $ \nabla f\colon\mathbb X\to\mathbb X $ is locally Lipschitz continuous.
Then each accumulation point
$ x^* $ of a sequence $ \{ x^k \} $ generated by \Cref{Alg:MonotoneProxGrad}
is an M-stationary point of \eqref{Eq:P}.
\end{theorem}

\begin{proof}
Let $ \{ x^k \}_K $ be a subsequence converging to $ x^* $. In view of
\Cref{Prop:xdiff}, it follows that also the subsequence $ \{ x^{k+1} \}_K $
converges to $ x^* $. Furthermore, \Cref{Prop:gammaxdiff} yields
$ \gamma_k \| x^{k+1} - x^k \| \to_K 0 $.
The minimizing property of $ x^{k+1} $, Fermat's rule, and the sum rule \eqref{eq:regular_sum_rule} imply that
\begin{equation}\label{Eq:OptCondSub}
   0 \in  \nabla f (x^{k}) + \gamma_k (x^{k+1}-x^k) 
   + \widehat\partial \phi (x^{k+1})
\end{equation}
holds for each $k\in K$. Hence, if we can show $ \phi (x^{k+1}) \to_K \phi (x^*) $, we can
take the limit $ k \to_K \infty $ in \eqref{Eq:OptCondSub} 
to obtain the desired statement $ 0 \in  \nabla f (x^*) + \partial \phi (x^*) $.
